-- =====================================================================
-- 0020 : Seed wilayah Cabang Dinas, sekolah, dan akun pemantau
--
-- Dibangkitkan tools/buat_seed_sekolah.py dari DATA SMA SMK SLB CABDIS DISDIK PROV SU.xlsx
-- 2084 sekolah, 35 kabupaten/kota, 14 wilayah.
--
-- NPSN BELUM ASLI. Sumber datanya tidak memuat kolom NPSN, sedangkan
-- kolomnya NOT NULL UNIQUE. Nilai sementara berbentuk SMT0000001 —
-- berawalan huruf sehingga tidak mungkin bentrok dengan NPSN asli yang
-- seluruhnya angka, dan mudah dicari saat penggantian:
--
--   SELECT count(*) FROM schools WHERE npsn LIKE 'SMT%';
--
-- Ganti dengan NPSN Kemdikbud sebelum sistem dipakai sungguhan;
-- tanpa itu, impor data resmi akan menghasilkan sekolah ganda.
-- =====================================================================

-- Provinsi
ON CONFLICT (code) DO NOTHING;

-- Cabang Dinas, anak provinsi
ON CONFLICT (code) DO NOTHING;

-- Kabupaten/kota, anak Cabang Dinas masing-masing
ON CONFLICT (code) DO NOTHING;

-- 2084 sekolah
ON CONFLICT (npsn) DO NOTHING;

